```go
package cart

import "errors"

// Item represents a product in the cart
type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart manages items for purchase
type ShoppingCart struct {
	items map[string]*Item
}

// NewShoppingCart creates a new empty cart
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

// AddItem adds an item or increases quantity if it exists
func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
		return
	}
	c.items[id] = &Item{
		ID:       id,
		Name:     name,
		Price:    price,
		Quantity: quantity,
	}
}

// RemoveItem removes an item entirely from the cart
func (c *ShoppingCart) RemoveItem(id string) error {
	if _, ok := c.items[id]; !ok {
		return errors.New("item not found")
	}
	delete(c.items, id)
	return nil
}

// UpdateQuantity changes the quantity of an existing item
func (c *ShoppingCart) UpdateQuantity(id string, quantity int) error {
	item, ok := c.items[id]
	if !ok {
		return errors.New("item not found")
	}
	if quantity <= 0 {
		delete(c.items, id)
		return nil
	}
	item.Quantity = quantity
	return nil
}

// GetItem retrieves an item by ID
func (c *ShoppingCart) GetItem(id string) (*Item, bool) {
	item, ok := c.items[id]
	return item, ok
}

// GetTotal calculates the total price of all items
func (c *ShoppingCart) GetTotal() float64 {
	total := 0.0
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// ItemCount returns the number of unique items
func (c *ShoppingCart) ItemCount() int {
	return len(c.items)
}

// Clear empties the cart
func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

// IsEmpty checks if cart has no items
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

